# >>> STATIC
_static_v() {
    cat <<-'ARGCEOF'
	0	kB/s
	1	total kB
	2	total bytes
	3	total MB
	4	MB/s
	5	GB/s
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
_choice_device() {
    if command -v ip >/dev/null 2>&1; then
        ip -o link show 2>/dev/null | gawk '
            {
                name = $2
                sub(/@.*$/, "", name)
                sub(/:$/, "", name)
                state = ""
                for (i = 1; i <= NF; i++) {
                    if ($i == "state") {
                        state = $(i + 1)
                    }
                }
                if (state == "") {
                    print name
                } else {
                    printf "%s\t%s\n", name, tolower(state)
                }
            }'
        return 0
    fi
    if [[ -d /sys/class/net ]]; then
        find /sys/class/net -mindepth 1 -maxdepth 1 | sed 's|.*/||'
        return 0
    fi
    if command -v ifconfig >/dev/null 2>&1; then
        ifconfig -l 2>/dev/null | tr ' ' '\n'
    fi
}

_choice_pid() {
    ps -Ao pid=,args= 2>/dev/null | gawk '
        {
            pid = $1
            desc = $0
            sub(/^[[:space:]]*/, "", desc)
            sub(/^[^[:space:]]+[[:space:]]+/, "", desc)
            if (length(desc) > 70) {
                desc = substr(desc, 1, 67) "..."
            }
            if (desc == "") {
                print pid
            } else {
                printf "%s\t%s\n", pid, desc
            }
        }'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
